package org.vef.mlkitlab;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;
import org.json.*;

/** Column geometry is confirmed before semantics. All inspector-facing text is English. */
public final class MappingActivity extends Activity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());
 private LinearLayout root,work;private TextView status;private Button choose,run,cancel;private Uri selected;
 private ColumnLayout layout,detected;private JSONObject raw;private Bitmap photo;private ColumnBoundsView overlay;
 private Runnable uiGuard;
 private String session,detectFile,resultFile;private int[] choices;private int page;private boolean busy,dead;private int workerPid;
 private android.content.SharedPreferences preferences;
 private File logs(){return new File(getFilesDir(),"diagnostics");}private File cache(){return new File(getFilesDir(),"mapping-cache");}
 private TextView text(LinearLayout parent,String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setPadding(0,10,0,8);parent.addView(t);return t;}
 private Button button(LinearLayout parent,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setOnClickListener(v->action.run());parent.addView(b);return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);preferences=getSharedPreferences("column_mapping",MODE_PRIVATE);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(20,25,20,25);scroll.addView(root);setContentView(scroll);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft()+20,i.getSystemWindowInsetTop()+20,i.getSystemWindowInsetRight()+20,i.getSystemWindowInsetBottom()+20);return i;});
  text(root,"VEF ML Kit Lab · Column Mapping",22);text(root,"Offline. Adjust column limits, map the five fields, then review every value. No automatic approval or VEF calculations.",16);
  choose=button(root,"Choose photograph",()->{if(busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,10);});
  run=button(root,"Detect columns",this::detect);cancel=button(root,"Cancel processing",this::cancel);cancel.setEnabled(false);
  button(root,"Resume saved mapping",()->{if(!busy)restore();});button(root,"Export persistent diagnostics (ZIP)",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"vef-column-mapping-diagnostics.zip");startActivityForResult(i,11);});
  button(root,"Back to previous diagnostic",()->{if(!busy)finish();});
  status=text(root,"Choose a photograph. Processing has a cumulative 15-second limit; time spent choosing columns is excluded.",16);work=new LinearLayout(this);work.setOrientation(LinearLayout.VERTICAL);root.addView(work);restore();
 }
 private void message(String s){if(!dead)status.setText(s);}
 private void setBusy(boolean b){if(uiGuard!=null)main.removeCallbacks(uiGuard);busy=b;choose.setEnabled(!b);run.setEnabled(!b);cancel.setEnabled(b);if(b){uiGuard=()->{if(busy){message("UI safety deadline reached. Stopping the isolated worker; export diagnostics.");cancel();}};main.postDelayed(uiGuard,16000);}}
 private ResultReceiver receiver(){return new ResultReceiver(main){@Override protected void onReceiveResult(int code,Bundle b){if(dead||!Objects.equals(session,b.getString("session")))return;workerPid=b.getInt("workerPid");message(b.getString("message",""));if(code==2){setBusy(false);String file=b.getString("resultFile");if(file.endsWith("-mapping-detect.json")){detectFile=file;loadDetected(null);}else{resultFile=file;page=2;saveDraft();loadResults(file);}}else if(code==3)setBusy(false);}};}
 private void detect(){if(busy)return;if(selected==null){message("Choose a photograph first.");return;}discardImage();session="map-"+UUID.randomUUID();detectFile=session+"-mapping-detect.json";resultFile=null;page=0;saveDraft();work.removeAllViews();setBusy(true);startService(new Intent(this,MappingOcrService.class).setAction("detect").putExtra("uri",selected).putExtra("session",session).putExtra("receiver",receiver()));}
 private void cancel(){if(!busy)return;startService(new Intent(this,MappingOcrService.class).setAction("cancel").putExtra("session",session));message("Cancellation requested. Persistent logs remain available.");main.postDelayed(()->{if(!busy||dead)return;try{ActivityManager am=(ActivityManager)getSystemService(ACTIVITY_SERVICE);for(ActivityManager.RunningAppProcessInfo p:am.getRunningAppProcesses())if(p.pid==workerPid&&p.uid==android.os.Process.myUid()&&p.processName.equals(getPackageName()+":column_mapping"))android.os.Process.killProcess(workerPid);}catch(Exception ignored){}setBusy(false);message("Mapping worker stopped. Export diagnostics for details.");},2000);}
 private void restore(){String saved=preferences.getString("draft",null);if(saved==null)return;try{JSONObject d=new JSONObject(saved);session=d.getString("session");detectFile=d.getString("detectFile");resultFile=d.optString("resultFile","");page=d.optInt("page");if(resultFile!=null&&!resultFile.isEmpty()&&page==2)loadResults(resultFile);else loadDetected(d);}catch(Exception e){message("Saved mapping could not be restored: "+e.getMessage());}}
 private void loadDetected(JSONObject draft){if(uiGuard!=null)main.removeCallbacks(uiGuard);busy=true;choose.setEnabled(false);run.setEnabled(false);cancel.setEnabled(false);io.execute(()->{try{JSONObject data=MappingOcrService.read(new File(logs(),detectFile));ColumnLayout initial=ColumnLayout.restore(data.getJSONObject("layout"),ColumnLayout.tokens(data.getJSONArray("tokensInOrientedOcrPixels")));ColumnLayout edited=draft!=null&&draft.has("layout")?ColumnLayout.restore(draft.getJSONObject("layout"),initial.words):ColumnLayout.restore(initial.json(),initial.words);int[] mapping=new int[edited.columns()];Arrays.fill(mapping,-2);if(draft!=null&&draft.has("choices")){JSONArray a=draft.getJSONArray("choices");if(a.length()==mapping.length)for(int i=0;i<mapping.length;i++)mapping[i]=a.getInt(i);}Bitmap p=MappingImage.decode(new File(cache(),session+".input"),1800);main.post(()->{if(dead){p.recycle();return;}raw=data;detected=initial;layout=edited;choices=mapping;releasePreview();photo=p;setBusy(false);message("Detected "+data.optInt("elementCount")+" OCR elements in "+data.optLong("ocrMs")+" ms. Check column limits before mapping.");if(page==1)showMapping();else showBounds();});}catch(Exception e){main.post(()->{setBusy(false);message("Cannot resume mapping: "+e.getMessage());});}});}
 private void saveDraft(){if(session==null||detectFile==null)return;try{JSONObject d=new JSONObject().put("session",session).put("detectFile",detectFile).put("page",page);if(layout!=null)d.put("layout",layout.json());if(choices!=null)d.put("choices",new JSONArray(choices));if(resultFile!=null)d.put("resultFile",resultFile);preferences.edit().putString("draft",d.toString()).apply();}catch(Exception e){message("Mapping state could not be saved.");}}
 private void showBounds(){page=0;work.removeAllViews();text(work,"Step 1 · Adjust Column Limits",21);text(work,"Drag blue separators. Tap a column to select it. Split a merged column or merge false splits. No OCR is repeated.",15);overlay=new ColumnBoundsView(this);work.addView(overlay);TextView selectedLabel=text(work,"Selected column: 1",16);LinearLayout samples=new LinearLayout(this);samples.setOrientation(LinearLayout.VERTICAL);work.addView(samples);
  Runnable refresh=()->{samples.removeAllViews();int c=Math.min(overlay.selected(),layout.columns()-1);selectedLabel.setText("Selected column: "+(c+1)+" of "+layout.columns());text(samples,"Header: "+(layout.header(c).isEmpty()?"No readable header":layout.header(c)),15);for(String v:layout.samples(c))text(samples,v,15);saveDraft();};
  overlay.set(layout,photo,true,new ColumnBoundsView.Listener(){public void selected(int c){refresh.run();}public void changed(){choices=new int[layout.columns()];Arrays.fill(choices,-2);refresh.run();}});
  button(work,"Split selected column",()->editBounds(()->layout.split(overlay.selected())));button(work,"Merge selected column with next",()->editBounds(()->layout.merge(overlay.selected())));
  button(work,"Set selected column limits precisely",this::preciseBounds);button(work,"Reset to detected limits",()->{try{layout=ColumnLayout.restore(detected.json(),detected.words);choices=new int[layout.columns()];Arrays.fill(choices,-2);showBounds();}catch(Exception e){message(e.getMessage());}});
  button(work,"Use compatible saved layout",this::useProfile);button(work,"Continue to Column Mapping",()->{try{ColumnLayout.restore(layout.json(),layout.words);showMapping();}catch(Exception e){message(e.getMessage());}});refresh.run();
 }
 private void editBounds(Runnable edit){try{edit.run();choices=new int[layout.columns()];Arrays.fill(choices,-2);showBounds();}catch(Exception e){message(e.getMessage());}}
 private void preciseBounds(){int col=overlay.selected();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);text(box,"Original-image pixels: left / right",16);EditText left=new EditText(this),right=new EditText(this);left.setInputType(android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);right.setInputType(android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);left.setText(String.format(Locale.ROOT,"%.1f",layout.bounds.get(col)));right.setText(String.format(Locale.ROOT,"%.1f",layout.bounds.get(col+1)));box.addView(left);box.addView(right);new AlertDialog.Builder(this).setTitle("Edit Column Limits").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{try{double l=Double.parseDouble(left.getText().toString()),r=Double.parseDouble(right.getText().toString());ColumnLayout trial=ColumnLayout.restore(layout.json(),layout.words);if(l<r){if(l>=trial.bounds.get(col+1)-3){trial.move(col+1,r);trial.move(col,l);}else{trial.move(col,l);trial.move(col+1,r);}}else throw new IllegalArgumentException("Left limit must precede right limit.");layout=trial;choices=new int[layout.columns()];Arrays.fill(choices,-2);showBounds();}catch(Exception e){message("Limits unchanged: "+e.getMessage());}}).show();}
 private void showMapping(){page=1;work.removeAllViews();text(work,"Step 2 · Column Mapping",21);text(work,"Select one field or Ignore for each physical column. Confirming mapping does not confirm OCR values.",15);overlay=new ColumnBoundsView(this);work.addView(overlay);overlay.set(layout,photo,false,null);if(choices==null||choices.length!=layout.columns()){choices=new int[layout.columns()];Arrays.fill(choices,-2);}String[] options={"Select field","Ignore","Port / Terminal","B/L Date","Cargo","Ship's Figures","B/L Figures"};
  for(int c=0;c<layout.columns();c++){final int col=c;String header=layout.header(c);text(work,"Column "+(c+1)+" · "+(header.isEmpty()?"No readable header":header),18);text(work,String.join("\n",layout.samples(c)),15);Spinner spinner=new Spinner(this);spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,options));spinner.setSelection(choices[c]+2);work.addView(spinner);spinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int position,long id){choices[col]=position-2;saveDraft();}});}
  button(work,"Back to Column Limits",this::showBounds);button(work,"Confirm Mapping",this::confirm);saveDraft();
 }
 private void useProfile(){try{JSONArray profiles=new JSONArray(preferences.getString("profiles","[]"));for(int i=profiles.length()-1;i>=0;i--){JSONObject p=profiles.getJSONObject(i);ColumnLayout trial=ColumnLayout.restore(detected.json(),detected.words);try{int[] restored=trial.applyProfile(p);layout=trial;choices=restored;message("Saved limits and fields proposed. Review the photograph and confirm again.");showBounds();return;}catch(IllegalArgumentException ignored){}}message("No compatible saved layout. Adjust limits and map the fields manually.");}catch(Exception e){message("Saved layout could not be loaded.");}}
 private void confirm(){if(busy)return;try{ColumnLayout.validateMapping(choices,layout.columns());JSONObject selection=new JSONObject().put("layout",layout.json()).put("choices",new JSONArray(choices)).put("confirmedByInspector",true).put("valuesConfirmed",false);JSONArray profiles=new JSONArray(preferences.getString("profiles","[]"));JSONObject profile=layout.profile(detected,choices);JSONArray next=new JSONArray();for(int i=0;i<profiles.length();i++)if(!profiles.getJSONObject(i).getString("signature").equals(profile.getString("signature"))&&next.length()<9)next.put(profiles.getJSONObject(i));next.put(profile);preferences.edit().putString("profiles",next.toString()).apply();setBusy(true);io.execute(()->{try{cache().mkdirs();MappingOcrService.save(new File(cache(),session+"-selection.json"),selection);main.post(()->startService(new Intent(this,MappingOcrService.class).setAction("apply").putExtra("session",session).putExtra("receiver",receiver())));}catch(Exception e){main.post(()->{setBusy(false);message("Cannot save confirmed mapping: "+e.getMessage());});}});}catch(Exception e){message(e.getMessage());}}
 private void loadResults(String file){io.execute(()->{try{JSONObject data=MappingOcrService.read(new File(logs(),file));JSONObject source=MappingOcrService.read(new File(logs(),data.getString("rawOcrFile")));ColumnLayout initial=ColumnLayout.restore(source.getJSONObject("layout"),ColumnLayout.tokens(source.getJSONArray("tokensInOrientedOcrPixels")));Bitmap preview=MappingImage.decode(new File(cache(),session+".input"),1800);main.post(()->{if(dead){preview.recycle();return;}raw=source;detected=initial;releasePreview();photo=preview;showResults(data);});}catch(Exception e){main.post(()->message("Cannot load saved results: "+e.getMessage()));}});}
 private void showResults(JSONObject data){if(dead)return;page=2;work.removeAllViews();try{JSONObject mapping=data.getJSONObject("mapping");layout=ColumnLayout.restore(mapping.getJSONObject("layout"),detected.words);JSONArray choiceArray=mapping.getJSONArray("choices");choices=new int[choiceArray.length()];for(int i=0;i<choices.length;i++)choices[i]=choiceArray.getInt(i);text(work,"Step 3 · Review Values",21);ColumnBoundsView originalView=new ColumnBoundsView(this);work.addView(originalView);originalView.set(layout,photo,false,null);text(work,data.getString("diagnostic"),16);text(work,"Active processing: "+data.optLong("usedActiveMs")+" ms / 15000 ms. Cell OCR calls: "+data.optInt("cellOcrCalls")+". All values remain unconfirmed.",15);button(work,"Edit Column Limits or Mapping",this::showBounds);JSONArray rows=data.getJSONArray("rows");for(int row=0;row<rows.length();row++){text(work,"Row "+(row+1),19);JSONObject cells=rows.getJSONObject(row).getJSONObject("cells");for(int c=0;c<5;c++){String field=ColumnLayout.FIELDS[c];JSONObject cell=cells.getJSONObject(field);TextView label=text(work,field+" · OCR: "+cell.getString("value")+"\n"+cell.getString("reason"),15);if(!"candidate".equals(cell.getString("status")))label.setBackgroundColor(0xffffedb0);if(!"candidate".equals(cell.getString("status")))label.append("\nReview Required");EditText edit=new EditText(this);edit.setSingleLine(true);edit.setText(cell.getString("value"));edit.setHint("Inspector correction — unconfirmed");edit.setContentDescription("Row "+(row+1)+" "+field+" inspector correction");work.addView(edit);CellReread.display(work,data,row,TableParser.LABELS[c]);}}message("Results are saved. Compare with the original photograph; no value was automatically approved.");saveDraft();}catch(Exception e){message("Cannot display mapping result: "+e.getMessage());}}
 private void discardImage(){releasePreview();if(session!=null)new File(cache(),session+".input").delete();layout=null;detected=null;raw=null;choices=null;}
 private void releasePreview(){if(photo!=null&&!photo.isRecycled())photo.recycle();photo=null;}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==10){selected=uri;try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}message("Photograph selected. Tap Detect columns.");}else if(request==11)io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri);ZipOutputStream zip=new ZipOutputStream(out)){File[] files=logs().listFiles((d,n)->n.endsWith(".json")||n.endsWith(".jsonl"));int count=0;if(files!=null)for(File f:files){zip.putNextEntry(new ZipEntry(f.getName()));try(InputStream in=new FileInputStream(f)){byte[] buffer=new byte[16384];int n;while((n=in.read(buffer))!=-1)zip.write(buffer,0,n);}zip.closeEntry();count++;}final int exported=count;main.post(()->message("Exported "+exported+" diagnostic files. No photographs or profiles included."));}catch(Exception e){main.post(()->message("Export failed: "+e.getMessage()));}});}
 @Override public void onBackPressed(){if(busy){cancel();return;}super.onBackPressed();}
 @Override protected void onDestroy(){dead=true;releasePreview();io.shutdown();super.onDestroy();}
}
